package com.nextaicommerce.platform.fba;
import static org.junit.jupiter.api.Assertions.*;
import static com.nextaicommerce.platform.fba.FbaReplenishmentMath.*;
import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class FbaOverstockPolicyTest {
 @Test void legacyJsonDefaultsTo120AndPreservesHigherLegacyTarget(){var json=new tools.jackson.databind.ObjectMapper();var old=json.readValue("{\"lowDays\":28,\"targetDays\":60,\"preparationDays\":0,\"transitDays\":0,\"receivingDays\":0,\"dailyOverride\":null}",Policy.class);assertEquals(120,old.overstockDays());assertFalse(old.leadTimesConfirmed());assertEquals(180,json.readValue("{\"lowDays\":28,\"targetDays\":180,\"preparationDays\":0,\"transitDays\":0,\"receivingDays\":0,\"dailyOverride\":null}",Policy.class).overstockDays());}
 @Test void explicitThresholdRoundTripsWithoutChangingOtherPolicyValues(){var json=new tools.jackson.databind.ObjectMapper();var p=new Policy(14,60,2,3,4,7d,true,130);assertEquals(p,json.readValue(json.writeValueAsString(p),Policy.class));assertEquals(9,p.lead());}
 @Test void rejectsThresholdBelowTargetOrBeyondExistingPlanningLimit(){assertThrows(IllegalArgumentException.class,()->new Policy(28,60,0,0,0,null,false,59));assertThrows(IllegalArgumentException.class,()->new Policy(28,60,0,0,0,null,false,366));}
 @Test void exact120IsHealthyAndMoreThan120OverstockWithoutChangingRecommendationMath(){var day=LocalDate.of(2026,11,19);var demand=new Demand(30,90,90,null,null);var p=new Policy(28,60,0,0,0,null,true,120);assertEquals("Healthy",estimate(day,demand,p,120d,false,100,List.of(),List.of()).status());assertEquals("Overstock",estimate(day,demand,p,121d,false,100,List.of(),List.of()).status());var a=estimate(day,demand,p,90d,false,100,List.of(),List.of());var b=estimate(day,demand,new Policy(28,60,0,0,0,null,true,60),90d,false,100,List.of(),List.of());assertEquals(a.recommended(),b.recommended());assertEquals(a.feasible(),b.feasible());assertEquals(a.shortfall(),b.shortfall());assertEquals(a.stockout(),b.stockout());assertEquals("Healthy",a.status());assertEquals("Overstock",b.status());}
 @Test void exactSkuThenBrandThenAccountAndOtherStoreNeverBorrowed(){UUID store=UUID.randomUUID(),other=UUID.randomUUID();var account=new Policy(28,60,0,0,0,null,true,120);var brand=new Policy(20,70,0,0,0,null,true,130);var sku=new Policy(14,80,0,0,0,null,true,140);var values=Map.of("ACCOUNT",account,"BRAND:Brand",brand,"SKU:"+store+":SKU",sku,"SKU:"+other+":other",sku);assertEquals(sku,selectPolicy(values,store,"SKU","Brand"));assertEquals(brand,selectPolicy(values,store,"other","Brand"));assertEquals(account,selectPolicy(values,store,"other","No brand"));}
 @Test void legacyCacheReclassificationChangesStatusOnly(){var r=new Result(4d,265L,100,165L,90d,LocalDate.of(2026,11,19),LocalDate.of(2027,2,17),null,"Overstock",List.of("Evidence preserved"),0,240);var p=new Policy(28,60,0,0,0,null,false);var result=displayClassification(r,p);assertEquals("Healthy",result.status());assertEquals(r.recommended(),result.recommended());assertEquals(r.feasible(),result.feasible());assertEquals(r.shortfall(),result.shortfall());assertEquals(r.warnings(),result.warnings());assertEquals(r.cover(),result.cover());assertEquals(r.stockout(),result.stockout());var unknown=new Result(null,null,0,null,null,null,null,null,"Inventory needs review",List.of(),0,0);assertSame(unknown,displayClassification(unknown,p));}
 @Test void legacySkuInheritsExplicitBrandThenAccountOverstockWithoutChangingItsLowTarget(){UUID store=UUID.randomUUID();var legacy=new Policy(14,80,0,0,0,null,true);var account=new Policy(28,60,0,0,0,null,true,150);var brand=new Policy(20,70,0,0,0,null,true,130);var scope="SKU:"+store+":SKU";var selected=selectPolicy(Map.of(scope,legacy,"ACCOUNT",account,"BRAND:Brand",brand),store,"SKU","Brand");assertEquals(130,selected.overstockDays());assertEquals(14,selected.lowDays());assertEquals(80,selected.targetDays());assertEquals(150,selectPolicy(Map.of(scope,legacy,"ACCOUNT",account),store,"SKU","Brand").overstockDays());}
}
